import manifest from '../../assets/arms/manifest.json'

/**
 * Responsive source sets for the arm artwork.
 *
 * Derivatives are generated by `npm run assets` and imported through Vite so
 * they get content-hashed filenames — which is what makes them safely
 * cacheable as immutable. Globbing keeps this file from turning into eighteen
 * hand-written imports that drift the moment the pipeline changes.
 */
const urls = import.meta.glob('../../assets/arms/*.{avif,webp,png}', {
  eager: true,
  query: '?url',
  import: 'default',
})

/** Widest first — browsers pick from srcset, but the fallback should be sane. */
const FORMAT_PRIORITY = ['avif', 'webp', 'png']

function buildSourceSets() {
  /** @type {Record<string, Record<string, Array<{url:string,width:number}>>>} */
  const collected = {}

  for (const [filePath, url] of Object.entries(urls)) {
    const fileName = filePath.split('/').pop()
    const match = fileName.match(/^(.+)-(\d+)\.(avif|webp|png)$/)
    if (!match) continue

    const [, id, width, format] = match

    collected[id] ??= {}
    collected[id][format] ??= []
    collected[id][format].push({ url, width: Number(width) })
  }

  const assets = {}

  for (const [id, formats] of Object.entries(collected)) {
    const meta = manifest[id]
    if (!meta) continue

    const sources = []

    for (const format of FORMAT_PRIORITY) {
      const entries = formats[format]
      if (!entries?.length) continue

      entries.sort((a, b) => a.width - b.width)
      sources.push({
        type: `image/${format}`,
        srcSet: entries.map((entry) => `${entry.url} ${entry.width}w`).join(', '),
      })
    }

    // Largest PNG is the last-resort <img src>, for anything that understands
    // neither AVIF nor WebP nor srcset.
    const pngs = formats.png ?? []
    const fallback = pngs.length ? pngs[pngs.length - 1].url : Object.values(formats).flat()[0]?.url

    assets[id] = {
      id,
      sources,
      fallback,
      width: meta.intrinsicWidth,
      height: meta.intrinsicHeight,
      aspectRatio: meta.aspectRatio,
    }
  }

  return assets
}

export const ARM_ASSETS = buildSourceSets()

/**
 * Build a `sizes` attribute from the layout's rendered widths.
 *
 * This has to mirror the composition or the browser picks the wrong file — the
 * single most common way a responsive image pipeline silently stops working.
 *
 * @param {number} mobileVw - rendered width on mobile, in vw
 * @param {number} desktopVw - rendered width on desktop, in vw
 * @param {number} breakpoint - px
 */
export function buildSizes(mobileVw, desktopVw, breakpoint) {
  return `(max-width: ${breakpoint}px) ${mobileVw}vw, ${desktopVw}vw`
}
